import React, { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { io, Socket } from 'socket.io-client';
import { LeaderboardEntry, Notification } from '../types';

interface SocketContextType {
  socket: Socket | null;
  connected: boolean;
  leaderboardUpdates: LeaderboardEntry[];
  notifications: Notification[];
  joinContest: (contestId: string) => void;
  leaveContest: (contestId: string) => void;
  markNotificationAsRead: (notificationId: string) => void;
}

const SocketContext = createContext<SocketContextType | undefined>(undefined);

export const useSocket = () => {
  const context = useContext(SocketContext);
  if (context === undefined) {
    throw new Error('useSocket must be used within a SocketProvider');
  }
  return context;
};

interface SocketProviderProps {
  children: ReactNode;
}

export const SocketProvider: React.FC<SocketProviderProps> = ({ children }) => {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [connected, setConnected] = useState(false);
  const [leaderboardUpdates, setLeaderboardUpdates] = useState<LeaderboardEntry[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    // Initialize socket connection
    const socketInstance = io(process.env.REACT_APP_SOCKET_URL || 'http://localhost:3001', {
      transports: ['websocket'],
      autoConnect: false
    });

    // Socket event listeners
    socketInstance.on('connect', () => {
      setConnected(true);
      console.log('Connected to server');
    });

    socketInstance.on('disconnect', () => {
      setConnected(false);
      console.log('Disconnected from server');
    });

    socketInstance.on('leaderboard_update', (data: LeaderboardEntry[]) => {
      setLeaderboardUpdates(data);
    });

    socketInstance.on('notification', (notification: Notification) => {
      setNotifications(prev => [notification, ...prev]);
    });

    socketInstance.on('match_start', (data: any) => {
      const notification: Notification = {
        id: `match-start-${data.matchId}`,
        userId: data.userId,
        title: 'Match Started!',
        message: `${data.homeTeam} vs ${data.awayTeam} has started`,
        type: 'match_start',
        isRead: false,
        createdAt: new Date().toISOString(),
        actionUrl: `/matches/${data.matchId}`
      };
      setNotifications(prev => [notification, ...prev]);
    });

    socketInstance.on('contest_deadline', (data: any) => {
      const notification: Notification = {
        id: `deadline-${data.contestId}`,
        userId: data.userId,
        title: 'Contest Deadline Approaching!',
        message: `Only 15 minutes left to join ${data.contestName}`,
        type: 'deadline',
        isRead: false,
        createdAt: new Date().toISOString(),
        actionUrl: `/contests/${data.contestId}`
      };
      setNotifications(prev => [notification, ...prev]);
    });

    socketInstance.on('contest_result', (data: any) => {
      const notification: Notification = {
        id: `result-${data.contestId}`,
        userId: data.userId,
        title: 'Contest Results Available!',
        message: `Results for ${data.contestName} are now available`,
        type: 'result',
        isRead: false,
        createdAt: new Date().toISOString(),
        actionUrl: `/contests/${data.contestId}/leaderboard`
      };
      setNotifications(prev => [notification, ...prev]);
    });

    setSocket(socketInstance);

    // Auto-connect socket if user is authenticated
    const token = localStorage.getItem('token');
    if (token) {
      socketInstance.connect();
    }

    return () => {
      socketInstance.disconnect();
    };
  }, []);

  const joinContest = (contestId: string) => {
    if (socket && connected) {
      socket.emit('join_contest', { contestId });
    }
  };

  const leaveContest = (contestId: string) => {
    if (socket && connected) {
      socket.emit('leave_contest', { contestId });
    }
  };

  const markNotificationAsRead = (notificationId: string) => {
    setNotifications(prev =>
      prev.map(notification =>
        notification.id === notificationId
          ? { ...notification, isRead: true }
          : notification
      )
    );
  };

  const value = {
    socket,
    connected,
    leaderboardUpdates,
    notifications,
    joinContest,
    leaveContest,
    markNotificationAsRead
  };

  return (
    <SocketContext.Provider value={value}>
      {children}
    </SocketContext.Provider>
  );
};
